/* GENERATED by gen_hcon_vault.py -- models are generated.
   HUB_QUOTE : 12 feed(s) over 12 source view(s), 3 run(s): opus_health_delta3, opus_health_legacy_v4, opus_health_v2
   LOADER SHAPE: ONE loader for this vault table; each run is a SEPARATE feed
   tagged by RECORD_SOURCE and SOURCE_RUN. RECORD_SOURCE is NEVER in the key.
   KEY FORM: md5(upper('HUB_QUOTE|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   REGISTRY RECONCILIATION, UNRESOLVED: unifying the hash form does NOT establish that the
   two runs' identifier spaces denote the same entities. 6 of the 14 shared hubs have ZERO
   business-key-column overlap between the runs. This hub is ONE KEY SPACE over the
   registries enumerated below; a false merge is unrecoverable after load.
     opus_health_delta3       2 registry/registries: HUB_QUOTE_BK__QUOTE_NO, HUB_QUOTE_BK__quote_no
     opus_health_legacy_v4    3 registry/registries: HUB_QUOTE_BK__QUOTE_REF, HUB_QUOTE_BK__QUOTE_REF_NO, HUB_QUOTE_BK__QUOTE_SUB_NO
     opus_health_v2           2 registry/registries: HUB_QUOTE_BK__QUOTATION_NO, HUB_QUOTE_BK__QUOTE_NO
*/

with feeds as (
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_REF as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__ecard_membr_del_dtls__ceeee04640') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_REF as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__ecard_pol_dtls_config__dade374328') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTATION_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__enroll_pol_dtls__a96c5cf9fd') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTATION_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__enroll_scr_dtls__deae1d26b0') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__quote_no as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_coverage_dtls__11eea68dcc') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_SUB_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_cust_dtls__c816e598f0') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_SUB_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_dtls__f45da7b3e2') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_SUB_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_imd_dtls__1bb3c646d2') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_SUB_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_maternity_dtls__054e65590e') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_mem_dtls__6bed07d177') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__grp_hlt_premium_dtls_typ1__c9a18b8345') }}
    union all
    select HUB_QUOTE_HK, HUB_QUOTE_BK__QUOTE_REF_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_quote__hg_pol_dtls__975947cf64') }}
)

select
    HUB_QUOTE_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
from feeds
where HUB_QUOTE_HK is not null
group by HUB_QUOTE_HK, BUSINESS_KEY
